test_setup_files.tests/discount_test.rs:
use dyncase::apply_discount;

#[test]
fn current_rate_applied() {
    let got = apply_discount(100.0);
    let want = 70.0;
    assert!(
        (got - want).abs() < 1e-9,
        "apply_discount(100.0) = {}, want {} (must use the CURRENT config::RATE = 0.30, after two compounding changes)",
        got, want
    );
}

